<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TanzaniaTrip | Tours</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><link rel="stylesheet" href="assets/css/tanzania.css"><style>.tour-hero{min-height:520px;background:linear-gradient(90deg,rgba(3,31,22,.92),rgba(3,31,22,.28)),url('https://images.unsplash.com/photo-1547471080-7cc2caa01a7e?auto=format&fit=crop&w=2200&q=88') center/cover;color:#fff;display:flex;align-items:center}.tour-search{background:#fff;border-radius:24px;padding:20px;box-shadow:0 22px 60px #031f1625;margin-top:-48px;position:relative;z-index:4}.tour-card{background:#fff;border-radius:26px;overflow:hidden;box-shadow:0 15px 45px #063b2912;height:100%;border:1px solid #e2e9e4;transition:.25s}.tour-card:hover{transform:translateY(-8px);box-shadow:0 26px 60px #063b2920}.tour-card img{width:100%;height:245px;object-fit:cover}.tour-body{padding:22px}.pill{border-radius:999px;background:#e7f1ec;color:#075238;padding:6px 10px;font-size:.72rem;font-weight:800}.route{border-left:2px solid #c9d9d0;padding-left:17px}.day{margin-bottom:14px}.day b{color:#08734a}.builder{background:#062d20;color:#fff;border-radius:28px;padding:30px}.builder-result{min-height:130px;background:#fff;color:#10251d;border-radius:20px;padding:20px}</style></head><body>
