<header class="tour-hero"><div class="container"><div class="eyebrow">Tanzania destination engine</div><h1 class="display-1 fw-bold mt-3">Tours that are<br><span style="color:#f0ce72">built as routes.</span></h1><p class="lead" style="max-width:760px">Select a region, choose the experience, change the number of days and inspect how the journey changes.</p></div></header>
<main><div class="container"><div class="tour-search"><div class="row g-2"><div class="col-lg-3"><select id="region" class="form-select form-select-lg"><option value="">All regions</option><option>Northern Circuit</option><option>Kilimanjaro</option><option>Zanzibar</option><option>Southern Highlands</option></select></div><div class="col-lg-3"><select id="interest" class="form-select form-select-lg"><option value="">All experiences</option><option value="wildlife">Wildlife</option><option value="mountain">Mountain</option><option value="beach">Beach</option><option value="culture">Culture</option><option value="nature">Nature</option></select></div><div class="col-lg-2"><input id="days" class="form-control form-control-lg" type="number" min="1" max="14" value="4"></div><div class="col-lg-2"><input id="people" class="form-control form-control-lg" type="number" min="1" max="20" value="2"></div><div class="col-lg-2"><button id="build" class="btn btn-tz btn-lg w-100">Build route</button></div></div></div></div>
<section class="section"><div class="container"><div class="d-flex justify-content-between align-items-end mb-5"><div><div class="kicker">Destination catalogue</div><h2>Choose the experience.</h2></div><span class="small text-secondary" id="tourCount">4 routes</span></div><div class="row g-4" id="tourGrid"><?php foreach($tours as $t): ?><div class="col-lg-6 tour-item" data-region="<?=$t['region']?>" data-tags="<?=$t['tags']?>"><article class="tour-card"><img src="<?=$t['img']?>" alt="<?=htmlspecialchars($t['name'])?>"><div class="tour-body"><div class="d-flex justify-content-between"><span class="pill"><?=$t['region']?></span><span class="small text-secondary"><?=$t['days']?> days</span></div><h3 class="mt-3"><?=htmlspecialchars($t['name'])?></h3><p class="text-secondary"><?=$t['places']?></p><div class="d-flex gap-2 flex-wrap mb-4"><?php foreach(explode(' ',$t['tags']) as $tag): ?><span class="badge text-bg-light text-capitalize"><?=$tag?></span><?php endforeach; ?></div><div class="d-flex justify-content-between align-items-center"><strong class="price"><?=$t['price']?></strong><button class="btn btn-gold inspect" data-id="<?=$t['id']?>">Explore route <i class="bi bi-arrow-right"></i></button></div></div></article></div><?php endforeach; ?></div></div></section>
<section class="section pt-0"><div class="container"><div class="builder"><div class="row g-4 align-items-center"><div class="col-lg-5"><div class="eyebrow">Dynamic route builder</div><h2 class="text-white mt-2">Change the trip. See the route change.</h2><p class="text-white-50">The route builder is intentionally data-driven: days and travellers affect the itinerary, room needs and transport estimate.</p></div><div class="col-lg-7"><div class="builder-result" id="result"><strong>Select a region or experience above.</strong><p class="text-secondary mb-0 mt-2">Your route will be assembled here instead of opening another static page.</p></div></div></div></div></div></section>
<section class="section"><div class="container"><div class="row g-4"><div class="col-lg-4"><div class="card-premium p-4 h-100"><i class="bi bi-map fs-2 text-success"></i><h4 class="mt-3">Geographic route</h4><p class="text-secondary">Future map layer can connect exact attractions, airports, bus stands and hotels.</p></div></div><div class="col-lg-4"><div class="card-premium p-4 h-100"><i class="bi bi-calendar3 fs-2 text-success"></i><h4 class="mt-3">Day sequencing</h4><p class="text-secondary">Activities are sequenced by day instead of presenting one flat tour description.</p></div></div><div class="col-lg-4"><div class="card-premium p-4 h-100"><i class="bi bi-building fs-2 text-success"></i><h4 class="mt-3">Connected hotels</h4><p class="text-secondary">A future route can hand travellers directly into room availability and reservation requests.</p></div></div></div></div></section></main>
<script>const tours=[...document.querySelectorAll('.tour-item')];function filter(){let r=document.querySelector('#region').value,i=document.querySelector('#interest').value,n=0;tours.forEach(x=>{let ok=(!r||x.dataset.region===r)&&(!i||x.dataset.tags.includes(i));x.style.display=ok?'block':'none';if(ok)n++});document.querySelector('#tourCount').textContent=n+' route'+(n===1?'':'s')}document.querySelector('#region').onchange=filter;document.querySelector('#interest').onchange=filter;document.querySelector('#build').onclick=()=>{let r=document.querySelector('#region').value||'Tanzania',i=document.querySelector('#interest').value||'mixed experiences',d=Math.max(1,+document.querySelector('#days').value||4),p=Math.max(1,+document.querySelector('#people').value||2),stops=['Arrival + orientation','Core destination experience','Local culture / food','Nature or attraction day','Flexible exploration','Departure / transfer'];let html='<div class="small text-success fw-bold mb-2">'+d+' DAYS · '+p+' TRAVELLER'+(p===1?'':'S')+' · '+r.toUpperCase()+'</div><h4>'+i.charAt(0).toUpperCase()+i.slice(1)+' route</h4><div class="route">';for(let x=0;x<d;x++)html+='<div class="day"><b>Day '+(x+1)+'</b> — '+stops[x%stops.length]+'<div class="small text-secondary">Hotel + transfer + experience layer is attached to this day.</div></div>';html+='</div>';document.querySelector('#result').innerHTML=html};document.querySelectorAll('.inspect').forEach(b=>b.onclick=()=>{document.querySelector('#result').innerHTML='<strong>Route '+b.dataset.id+' selected.</strong><p class="text-secondary mb-0 mt-2">This is where the production version will load the route graph, accommodation choices, transfer legs, attraction details and live availability.</p>';window.scrollTo({top:document.querySelector('.builder').offsetTop-80,behavior:'smooth'})});</script></body></html>